  real y;
  if (x >= -2 && x <= 0) {y = x;}
  if (x >= 0 && x <= 3) {y = 2 - x;}
  if (x >= 3 && x <= 4) {y = x - 4;}
  return(y);
}

real funca(real x) {
  return(2*func(abs(x)));
}

real funcb(real x) {
  real y = max(0,2*func(x));
  return(y);
}

real funcd(real x) {
  return(2*abs(func(x)));
}

