  real y;
  if (x >= -2 && x <= 0) {y = x^2 - 1;}
  if (x >= 0 && x <= 3) {y = -x + 1;}
  if (x >= 3 && x <= 4) {y = 1;}
  return(y);
}

real funca(real x) {
  return(func(2 - x));
}

real funcb(real x) {
  real y = max(0,func(x));
  return(y);
}

