Determine the graph of the function $y = \log_{1/2} (g(x) + 1)$.

[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -3 && x <= 0) {y = 2*sin((x + 3)*2*3.14/3);}
  if (x >= 0 && x <= 2) {y = cos((x - 2)*2*3.14/2) - 1;}
  if (x >= 2 && x <= 3) {y = 2*sqrt(x - 2);}
  return(y);
}

real funca(real x) {
  return(func(abs(x)));
}

real funcb(real x) {
  real y = max(0,func(x));
  return(y);
}

real funcd(real x) {
  return(abs(func(x)));
}

real funce(real x) {
  return(abs(func(-x)));
}

real funcf(real x) {
  real y;
  if (func(x) + 1 <= 0) {y = -(-ln(func(x) + 1)/ln(0.5));}
  if (func(x) + 1 > 0) {y = -ln(func(x) + 1)/ln(0.5);}
  return(y);
}

for (n = 1; n <= 5; ++n) {
