Which is the graph of $y = g(x) + 2$?

[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -2 && x <= 1) {y = 1 - x;}
  if (x >= 1 && x <= 3) {y = sqrt(9 - (x - 3)^2) - 2;}
  if (x >= 3 && x <= 4) {y = 3*(x - 3);}
  return(y);
}

real funca(real x) {
  return(func(x) + 2);
}

real funcc(real x) {
  return(func(x) - 2);
}

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
    draw(graf[n],(i,-5)--(i,5),gray(0.7));
    draw(graf[n],(-5,i)--(5,i),gray(0.7));
  }
  draw(graf[n],(-5,0)--(5,0),Arrows(6));
  draw(graf[n],(0,-5)--(0,5),Arrows(6));

  label(graf[n],"$x$", (5,0), E);
  label(graf[n],"$y$", (0,5), N);
}

draw(graf[1],graph(funca,-2,4),blue);
draw(graf[2],shift((1,1))*graph(func,-2,4),blue);
draw(graf[3],graph(funcc,-2,4),blue);
draw(graf[4],shift((-1,1))*graph(func,-2,4),blue);
draw(graf[5],shift((-1,-1))*graph(func,-2,4),blue);

label(graf[1], "A", (0,-6));
label(graf[2], "B", (0,-6));
label(graf[3], "C", (0,-6));
label(graf[4], "D", (0,-6));
label(graf[5], "E", (0,-6));

add(graf[1]);
add(shift((12,0))*(graf[2]));
add(shift((24,0))*(graf[3]));
add(shift((6,-12))*(graf[4]));
add(shift((18,-12))*(graf[5]));
[/asy]

