for(int i = -4; i <= 5; ++i) {
	draw((i,-1)--(i,6), dashed+mediumgrey);
}

for(int i = 1; i <= 6; ++i) {
	draw((-4,i)--(5,i), dashed+mediumgrey);
}

Label laxis; laxis.p=fontsize(10);

xaxis("$x$",-4.36,5.56,defaultpen+black,Ticks(laxis,Step=1.0,Size=2,OmitTick(0)),Arrows(6),above=true); yaxis("$y$",-0.92,6.12,defaultpen+black,Ticks(laxis,Step=1.0,Size=2,OmitTick(0)),Arrows(6),above=true);

// draw((min,(-(-9)-(0)*xmin)/3)--(xmax,(-(-9)-(0)*xmax)/3),linetype("6pt 6pt"));

label("$f(x)$",(-3.52,4.6),SE*lsf);

draw((xmin,(-(0)-(-2)*xmin)/-2)--(-1,(-(0)-(-2)*-1)/-2),linewidth(1.2),blue); draw((-1,1)--(3,5),linewidth(1.2),blue); draw((3,(-(-16)-(2)*3)/2)--(xmax,(-(-16)-(2)*xmax)/2),linewidth(1.2),blue); draw((-4,3)--(-1,1)--(1,3)--(3,5)--(5,3),linewidth(1.2),red);

